      bool hasPred = (it != S.begin());\n        long long pred = 0;\n        if (hasPred) pred = *prev(it);\n        auto itNext = next(it);\n        bool hasSucc = (itNext != S.end());\n        long long succ = hasSucc ? *itNext : 0;\n\n        if (hasPred) {\n            auto gapIt = gaps.find(x - pred);\n            if (gapIt != gaps.end()) gaps.erase(gapIt);\n        }\n        if (hasSucc) {\n            auto gapIt = gaps.find(succ - x);\n            if (gapIt != gaps.end()) gaps.erase(gapIt);\n        }\n        if (hasPred && hasSucc) {\n            gaps.insert(succ - pred);\n        }\n        S.erase(it);\n    };\n\n    auto addIndex = [&](int idx) {\n        int id = comp[idx];\n        long long val = a[idx];\n        int c = cnt[id];\n        cnt[id]++;\n        if (c == 0) {\n            insertValue(val);\n        } else if (c == 1) {\n            // 1 -> 2\n            dupCount++;\n            eraseValue(val);\n        } else {\n            // 2 or more, nothing changes in structure\n        }\n    };\n\n    auto removeIndex = [&](int idx) {\n        int id = comp[idx];\n        long long val = a[idx];\n        int c = cnt[id];\n        cnt[id]--;\n        if (c == 1) {\n            // 1 -> 0\n            eraseValue(val);\n        } else if (c == 2) {\n            // 2 -> 1\n            insertValue(val);\n            dupCount--;\n        } else {\n            // >=3 -> still duplicates present\n        }\n    };\n\n    int block = max(1, (int)sqrt(n));\n    vector<Query> q = queries;\n    sort(q.begin(), q.end(), [block](const Query& A, const Query& B) {\n        int blockA = A.l / block;\n        int blockB = B.l / block;\n        if (blockA != blockB) return blockA < blockB;\n        if (blockA & 1) return A.r > B.r;\n        return A.r < B.r;\n    });\n\n    vector<long long> ans(m);\n    int curL = 0, curR = -1;\n\n    for (auto &qq : q) {\n        int L = qq.l, R = qq.r;\n        while (curL > L) { curL--; addIndex(curL); }\n        while (curR <